 $('rotateDesign').onclick=()=>{decalEditor?.reset();groundEditor?.reset();propEditor?.reset();previewPaint?.reset();rotation=(rotation+1)%4;render();};$('rotateBackDesign').onclick=()=>{decalEditor?.reset();groundEditor?.reset();propEditor?.reset();previewPaint?.reset();rotation=(rotation+3)%4;render();};function selectSlot(){importRequest++;source=Number($('designSource').value);const [width,height]=$('designFootprint').value.split('x').map(Number);footprint={width,height};draft=structuredClone(city.buildingDesigns?.[slot()]||defaultBuildingDesign(slot()));fill();$('designStatus').textContent='Loaded this style and footprint’s saved model, or a fresh draft.';}$('designSource').onchange=selectSlot;$('designFootprint').onchange=selectSlot;
