 $('importDesign').onclick=()=>$('designFile').click();$('designFile').onchange=async event=>{const file=event.target.files[0],id=++importRequest;if(!file)return;try{if(file.size>32768)throw Error('Building files must be smaller than 32 KB.');const imported=importBuildingDesign(await file.text());if(id!==importRequest||!document.contains(canvas)||$('designPreview')!==canvas)return;if(!sameBuildingFootprint(imported.footprint,footprint))throw Error('This file has a different tile footprint. Select its footprint before importing.');draft=imported;fill();$('designStatus').textContent='Imported as a draft. Apply to city when ready.';}catch(e){if(id===importRequest&&document.contains(canvas)&&$('designPreview')===canvas)$('designStatus').textContent=e.message;}finally{if(id===importRequest)event.target.value='';}};
